WITH not_flagged AS (SELECT s.* FROM orders s WHERE EXISTS (SELECT 1 FROM order_items c WHERE c.order_id = s.id AND c.order_id IN (3, 14, 33, 40))) SELECT store_id, CORR(shipping_fee, amount) AS corr_shipping_fee_amount, SUM(CASE WHEN status = 'PENDING' THEN shipping_fee ELSE 0 END) AS pending_shipping_fee, COUNT_IF(status = 'CANCELLED') AS cancelled_events FROM not_flagged GROUP BY store_id HAVING cancelled_events > 1 ORDER BY cancelled_events DESC NULLS FIRST;
